#!/usr/bin/env bash
# apply-machine-6shots.sh · EcoWoods
# Upgrades "The Craft" gallery from 3 to 6 photos per machine by merging the
# second image set (gallery-machines (1).zip) as shots 04/05/06 under the
# canonical slugs, then rebuilding the component + image map. Idempotent.
set -euo pipefail
[[ -f pnpm-workspace.yaml && -d apps/web ]] || { echo "X run from repo root"; exit 1; }
Z="gallery-machines (1).zip"
[[ -f "$Z" ]] || { echo "X '$Z' not found in repo root"; exit 1; }
DEST=apps/web/public/gallery-machines
mkdir -p "$DEST"

echo ">> Extracting + mapping set 2 into shots 04/05/06"
TMP=$(mktemp -d); unzip -o -q "$Z" -d "$TMP"
python3 - "$TMP" "$DEST" <<'PYEOF'
import sys, glob, os, re, shutil
tmp, dest = sys.argv[1], sys.argv[2]
MAP={'drum-sander':'drum-sander','edger':'edger','finish-applicators':'finish-applicators',
'jamb-saw':'jamb-saw','moisture-meter':'moisture-meter','table-saw':'table-saw',
'floor-buffer':'buffer','hepa-dust-containment':'dust-containment','pneumatic-nailer':'flooring-nailer',
'compound-miter-saw':'miter-saw','random-orbital-sander':'orbital-sander','router-detail-tools':'router'}
SHOT={'01-inuse':'04-inuse','02-detail':'05-detail','03-context':'06-context'}
n=0
for src in glob.glob(tmp+'/**/*.webp', recursive=True):
    if '__MACOSX' in src: continue
    m=re.match(r'(.+)-(01-inuse|02-detail|03-context)\.webp$', os.path.basename(src))
    if not m: continue
    slug2, shot = m.group(1), m.group(2)
    if slug2 not in MAP: continue
    shutil.copy(src, f'{dest}/{MAP[slug2]}-{SHOT[shot]}.webp'); n+=1
print(f'   -> placed {n} images (04/05/06)')
PYEOF
rm -rf "$TMP"
echo "   -> total: $(ls "$DEST"/*.webp | wc -l | tr -d ' ') webp (want 72)"

echo ">> Rewriting data/machine-images.ts (6 per machine)"
base64 -d > apps/web/app/data/machine-images.ts <<'B64_MI'

B64_MI
echo ">> Rewriting components/MachineCatalog.tsx (6-shot rotation + 6-photo lightbox)"
base64 -d > apps/web/app/components/MachineCatalog.tsx <<'B64_MC'

B64_MC

echo ">> Adding thumbnail-wrap CSS (idempotent)"
node - apps/web/app/globals.css <<'NODE'
const fs=require('fs'); const p=process.argv[2]; let s=fs.readFileSync(p,'utf8');
s=s.replace(/\n?\/\* === EW:MACHINE-THUMBS START === \*\/[\s\S]*?\/\* === EW:MACHINE-THUMBS END === \*\/\n?/g,'\n');
const b='/* === EW:MACHINE-THUMBS START === */\n.fc-thumbs { flex-wrap: wrap; }\n.fc-thumb { flex: 0 0 calc(33.333% - 0.37rem); }\n/* === EW:MACHINE-THUMBS END === */';
if(!s.endsWith('\n')) s+='\n'; s+='\n'+b+'\n'; fs.writeFileSync(p,s);
console.log('   -> thumb-wrap CSS in place:', s.includes('EW:MACHINE-THUMBS'));
NODE
echo "OK  Done. rm -rf apps/web/.next && pnpm --filter web dev  (then commit + push)"
